console.log('📝 Activity Logger module loaded');const ACTIVITY_TYPES ={user_added:{icon:'fa-user-plus',priority:'medium' },user_updated:{icon:'fa-user-edit',priority:'low' },user_deleted:{icon:'fa-user-times',priority:'high' },collector_added:{icon:'fa-truck',priority:'medium' },collector_updated:{icon:'fa-truck',priority:'low' },collector_deleted:{icon:'fa-truck-loading',priority:'high' },schedule_created:{icon:'fa-calendar-plus',priority:'medium' },schedule_updated:{icon:'fa-calendar-alt',priority:'low' },schedule_deleted:{icon:'fa-calendar-times',priority:'medium' },feedback_received:{icon:'fa-comment',priority:'low' },settings_updated:{icon:'fa-cog',priority:'low' },sensor_alert:{icon:'fa-exclamation-triangle',priority:'urgent' },sensor_updated:{icon:'fa-microchip',priority:'low' },system_action:{icon:'fa-server',priority:'medium' } };export function logActivity(type,message,priority = null,metadata ={}){const activityInfo = ACTIVITY_TYPES[type] ||{icon:'fa-info-circle',priority:'low' };const finalPriority = priority || activityInfo.priority;const activity ={id:`activity-${Date.now()}-${Math.random().toString(36).substr(2,9)}`,type:type,category:getCategoryFromType(type),message:message,priority:finalPriority,icon:activityInfo.icon,timestamp:new Date().toISOString(),metadata:metadata,read:false };storeRecentActivity(activity);if (finalPriority === 'urgent' || finalPriority === 'high'){storeAsNotification(activity);} console.log('📝 Activity logged:',activity);return activity;} function getCategoryFromType(type){if (type.includes('user')) return 'user';if (type.includes('collector')) return 'collector';if (type.includes('schedule')) return 'schedule';if (type.includes('sensor')) return 'iot';if (type.includes('feedback')) return 'feedback';if (type.includes('settings')) return 'system';return 'system';} function storeRecentActivity(activity){const stored = localStorage.getItem('ecosched_recent_activity');const activities = stored ? JSON.parse(stored) :[];activities.unshift(activity);const trimmed = activities.slice(0,50);localStorage.setItem('ecosched_recent_activity',JSON.stringify(trimmed));} function storeAsNotification(activity){const stored = localStorage.getItem('ecosched_notifications');const notifications = stored ? JSON.parse(stored) :[];const notification ={id:activity.id,type:activity.category,priority:activity.priority,title:getNotificationTitle(activity.type,activity.priority),message:activity.message,timestamp:activity.timestamp,read:false,metadata:activity.metadata };notifications.unshift(notification);const trimmed = notifications.slice(0,100);localStorage.setItem('ecosched_notifications',JSON.stringify(trimmed));} function getNotificationTitle(type,priority){if (priority === 'urgent') return '🚨 Urgent Action';if (priority === 'high') return '⚠️ Important Update';switch (type){case 'user_added':return '👤 New User Added';case 'user_deleted':return '🗑️ User Removed';case 'collector_added':return '🚚 New Collector Added';case 'collector_deleted':return '🗑️ Collector Removed';case 'schedule_deleted':return '📅 Schedule Deleted';default:return 'ℹ️ System Update';} } export function getRecentActivities(limit = 10){const stored = localStorage.getItem('ecosched_recent_activity');const activities = stored ? JSON.parse(stored) :[];return activities.slice(0,limit);} export function clearOldActivities(days = 7){const stored = localStorage.getItem('ecosched_recent_activity');if (!stored) return;const activities = JSON.parse(stored);const cutoffDate = new Date();cutoffDate.setDate(cutoffDate.getDate() - days);const filtered = activities.filter(activity =>{return new Date(activity.timestamp) > cutoffDate;});localStorage.setItem('ecosched_recent_activity',JSON.stringify(filtered));console.log(`🗑️ Cleared ${activities.length - filtered.length} old activities`);} clearOldActivities(7);